for Bi,Ci in pairs(xi)do
local Di=type(Ci)==Skc[1370]and type(Ci.override_stats)==Skc[1370]and(Ci.override_stats[1]or Ci.override_stats[Skc[1507]])or nil
if type(Di)==Skc[1370]then
