end
local Wv=G.Units[Uv]
local Xv=Wv.evolve and Wv.evolve.evolve_unit or Uv
local Yv={id=Uv,to=Xv,coins=G.cur(Skc[1747]),itemCost=0,needCoins=0}
for Zv,_v in pairs(Wv.evolve and Wv.evolve.normal and Wv.evolve.normal.item_requirement or{})do
local aw=G.SaleEvent[_v.item_id]
if aw and type(aw.resource_cost)==Skc[1370]and aw.resource_cost.id==Skc[1747]then
Yv.item,Yv.itemCost=_v.item_id,tonumber(aw.resource_cost.amount)or 0
end
end
Yv.haveItem=Yv.item~=nil and W.have(Yv.item)>0
local bw,cw=O.hatched[Uv]or false,false
for dw,ew in pairs(Vv.collection.owned_units)do
if ew.unit_id==Uv then
bw=true
end
if ew.unit_id==Xv then
cw=true
end
end
if cw then
Yv.step=Skc[1748]
elseif not bw then
Yv.step,Yv.needCoins=Skc[1749],1
elseif Yv.item and not Yv.haveItem then
Yv.step,Yv.needCoins=Skc[1717],math.max(0,Yv.itemCost-Yv.coins)
else
Yv.step=Skc[1750]
end
