return hw..string.format(Skc[1754],M.name(fw.id))
end
local iw=math.max(H.aprilFloor,fw.haveItem and 0 or fw.itemCost)
local jw=gw and gw.pity_data and gw.pity_data.April2025
local kw=jw and tonumber(jw.opens_since_mythic)
return hw..string.format(Skc[1755]..Skc[1756]..Skc[1757],M.name(fw.id),L.fmt(fw.coins),math.max(0,math.floor((fw.coins-iw)/1500)),L.fmt(iw),M.name(fw.id),kw and string.format(Skc[1758],kw)or Skc[299],math.max(H.aprilValue,H.goalCoinValue),H.summonApril and Skc[1759]or Skc[1760])
elseif fw.step==Skc[1717]then
return hw..string.format(Skc[1761],M.name(fw.id),L.fmt(fw.itemCost),L.fmt(fw.coins))
elseif fw.step==Skc[1750]then
return hw..Skc[1762]
end
return hw..Skc[1763]
end
