if zx and os.time()-zx.at<3600 then
return zx.n
end
local Ax=0
pcall(function()
local Bx=G.Levels[wx]
local Cx=V.info(V.slim and V.slim(Bx)or Bx,Skc[1785]..yx)
local Dx=false
for Ex,Fx in pairs(Cx.configs or{})do
if xx[Ex]or(type(Fx)==Skc[1370]and xx[Fx.unit_id or Skc[299]])then
Dx=true
break
end
end
if not Dx then
