end
task.wait(1.2)
if WE.e.u._equipped_relic~=XE then
j.log(1,Skc[1824],string.format(Skc[1848],(G.Items[(zE.inventory:get_item_by_uuid(XE)or{}).item_id]or{}).name or Skc[1849],M.name(WE.e.id),FE(eF)))
j.backoff(Skc[1844],300)
I.str.relicAt=0
