for pF,qF in ipairs(nF and cb.core()or{})do
local rF=nF.collection:get_unit_by_uuid(qF)
if rF then
oF=oF+math.max(0,cb.xpFor(rF.unit_id,cb.cap(rF))-(tonumber(rF.xp)or 0))
end
