end
function cb.plan()
local sF=G.session()
if not sF then
return{}
end
local tF={}
local uF=cb.core()
local vF=cb.foodHeld()
local wF=0
for xF,yF in ipairs(vF)do
wF=wF+yF.n*yF.xp
end
local zF=H.autoFuse and H.fuseUnit~=Skc[299]and H.fuseUnit or nil
local AF=(I.fuseInfo and tonumber(I.fuseInfo.requirement))or(I.lb and tonumber(I.lb.requirement))or 12
local BF=W.have(Skc[1817])
for CF,DF in ipairs(uF)do
local EF=sF.collection:get_unit_by_uuid(DF)
if EF then
local FF,GF=EF.unit_id,M.name(EF.unit_id)
local HF=cb.role(FF)
if H.teamXp and wF>0 then
local IF,JF=cb.gainXp(EF,wF)
local KF,LF=cb.gainXp(EF,500000)
local MF=LF>0 and KF/LF*JF or 0
if JF>0 and MF>0 then
table.insert(tF,{kind=Skc[1853],uuid=DF,name=GF,gain=MF,add=JF,text=string.format(Skc[1854],GF,L.fmt(JF),cb.level(EF),cb.level({unit_id=FF,xp=(tonumber(EF.xp)or 0)+JF}),MF)})
end
end
local NF=I.str.fuseNo and tonumber(I.str.fuseNo[DF])
if H.teamFuse and cb.lb(EF)==0 and HF~=Skc[1388]and DF~=zF and not(NF and os.time()-NF<86400)then
local OF=cb.gainFuse(EF)
local PF=cb.xpFor(FF,cb.cap(EF))<=(tonumber(EF.xp)or 0)
local QF,RF,SF=pcall(O.fuseFuel,EF,AF)
SF=QF and SF or 0
local TF=(not PF and Skc[1855])or(BF<1 and Skc[1856])or(SF<AF and string.format(Skc[1857],math.floor(SF),math.floor(AF)))or nil
table.insert(tF,{kind=Skc[1858],uuid=DF,name=GF,gain=OF,blocked=TF,text=string.format(Skc[1859],GF,OF)})
end
end
end
table.sort(tF,function(UF,VF)
if UF.gain~=VF.gain then
return UF.gain>VF.gain
end
return UF.text<VF.text
end)
for WF in pairs(M._mult)do
if type(WF)==Skc[1372]and WF:sub(1,5)==Skc[1828]then
M._mult[WF]=nil
end
end
I.str.acts,I.str.actsAt={},os.time()
for XF=1,math.min(12,#tF)do
local YF=tF[XF]
table.insert(I.str.acts,{kind=YF.kind,uuid=YF.uuid,name=YF.name,gain=YF.gain,text=YF.text,blocked=YF.blocked})
end
return tF
end
function cb.itemWorth(ZF)
if not(I.str.acts and os.time()-(tonumber(I.str.actsAt)or 0)<900)then
return nil
end
local _F={}
for aG,bG in ipairs(I.str.acts)do
if bG.gain and(not _F[bG.kind]or bG.gain>_F[bG.kind])then
_F[bG.kind]=bG.gain
end
end
local cG=H.strengthValue or 300
if ZF==Skc[1817]then
return _F.fuse and math.max(G.ITEM_VALUE.divine_wish or 400,_F.fuse*cG)or nil
end
