function cb.xpRate()
local dG=G.session()
if not dG then
return 0
end
local eG=0
for fG,gG in ipairs(cb.core())do
local hG=dG.collection:get_unit_by_uuid(gG)
if hG then
local iG,jG=cb.gainXp(hG,500000)
if jG>0 then
eG=math.max(eG,iG/jG)
end
end
end
local kG=eG*(H.strengthValue or 300)
if(tonumber(G.cur(Skc[1432]))or 0)>(H.xpGoldFloor or 100000)then
kG=math.min(kG,(G.GOLD_VALUE or 0.02)/14)
end
return kG
end
function cb.xpGuess(lG)
local mG=lG.level and G.Levels[lG.level]
if not mG then
return 0
end
local nG=math.min(9,tonumber(mG.story_world_rank)or tonumber(lG.rank)or 9)
local oG=tonumber(mG.story_level_rank)or 6
local pG=(lG.kind==Skc[1406]and 1.5 or 1)*(nG>5 and 2 or 1)
local qG=2.1564^(nG-1)*(40+10*oG)/pG
if lG.kind==Skc[1389]then
qG=3*30*2.1564^(nG-1)/pG
end
local rG=nG>=9 and 0.3 or(nG>=7 and 0.5 or 1)
return qG*rG*6
end
function cb.modeBonus(sG)
if not(H.team and H.teamXp)or sG.kind==Skc[1390]or sG.kind==Skc[1387]then
return 0
end
local tG=cb._xpRate and os.time()-(cb._xpRateAt or 0)<300 and cb._xpRate or nil
if not tG then
tG=cb.xpRate()
cb._xpRate,cb._xpRateAt=tG,os.time()
end
if tG<=0 then
return 0
end
local uG=I.modes and I.modes[sG.key]
local vG=tonumber(uG and uG.xp)or cb.xpGuess(sG)
local wG=vG*tG
if wG<1 then
return 0
end
return wG,string.format(Skc[1860],L.fmt(vG),math.floor(wG+0.5))
end
function cb.xpSettle()
local xG=I.lastRun
if not(xG and type(xG.xp0)==Skc[1370]and xG.key)then
return
end
local yG=G.session()
if not yG then
return
end
local zG,AG=0,0
for BG,CG in pairs(xG.xp0)do
local EG=yG.collection:get_unit_by_uuid(BG)
if EG then
zG=zG+math.max(0,(tonumber(EG.xp)or 0)-(tonumber(CG)or 0))
AG=AG+1
end
end
I.lastRun=nil
if AG==0 then
return
end
local FG=N.rec(xG.key)
FG.xp=FG.xp and(FG.xp+(zG-FG.xp)*0.3)or zG
if zG>0 then
j.log(2,cb.LOG,string.format(Skc[1861],xG.key,L.fmt(zG)))
end
j.saveSoon()
end
function cb.note(GG)
j.log(1,cb.LOG,GG)
table.insert(I.str.log,1,{at=os.time(),msg=GG})
while#I.str.log>20 do
table.remove(I.str.log)
end
j.saveSoon()
end
function cb.run(HG)
local IG=G.session()
local JG=IG and IG.collection:get_unit_by_uuid(HG.uuid)
if not JG then
return
end
if HG.kind==Skc[1853]then
local KG=M.trait(JG)
local LG=KG==Skc[1862]and 1.5 or 1
local MG=math.max(0,cb.xpFor(JG.unit_id,cb.cap(JG))-(tonumber(JG.xp)or 0))
local NG,OG,PG={},0,0
for QG,RG in ipairs(cb.foodHeld())do
local SG=RG.xp*LG
local TG=math.min(RG.n,math.floor((MG-OG)/math.max(1,SG)))
if TG>0 then
NG[RG.id]=TG
OG=OG+TG*SG
PG=PG+TG
end
end
if PG==0 then
I.str.feedNote=HG.name..Skc[1863]
return
end
local UG,VG=tonumber(JG.xp)or 0,cb.level(JG)
local WG,XG=j.request(Skc[1853],Skc[1864],HG.uuid,NG)
local YG=L.now()
while L.now()-YG<4 and(tonumber((IG.collection:get_unit_by_uuid(HG.uuid)or JG).xp)or 0)<=UG do
task.wait(0.25)
end
local ZG=IG.collection:get_unit_by_uuid(HG.uuid)or JG
local aH=(tonumber(ZG.xp)or 0)-UG
if aH>0 then
Q.add(string.format(Skc[1865],PG,HG.name),PG,Skc[1866],string.format(Skc[1867],L.fmt(aH),VG,cb.level(ZG)))
cb.note(string.format(Skc[1868],HG.name,PG,L.fmt(aH),VG,cb.level(ZG),math.abs(aH-OG)>OG*0.1 and string.format(Skc[1869],L.fmt(OG))or Skc[299]))
else
cb.note(string.format(Skc[1870],HG.name,tostring(WG and XG or Skc[1621])))
j.backoff(Skc[1853],600)
end
elseif HG.kind==Skc[1858]then
O.fuseInto(HG.uuid,false)
end
end
function cb.slotOf(bH)
local cH=G.session()
for dH,eH in pairs(cH and cH.profile_data.collection.equipped_units or{})do
if eH==bH then
return tonumber(dH)or dH
end
end
