end
function cb.reequip()
local fH=I.str.reequip
if not fH then
return true
end
local gH=G.session()
local hH=gH and gH.collection:get_unit_by_uuid(fH.uuid)
if not hH then
I.str.reequip=nil
return true
end
for iH=1,3 do
if cb.slotOf(fH.uuid)then
break
end
j.request(Skc[1871],Skc[1872],fH.uuid)
local jH=L.now()
while L.now()-jH<3 and not cb.slotOf(fH.uuid)do
task.wait(0.25)
end
end
N._sigAt=nil
if cb.slotOf(fH.uuid)then
I.str.reequip=nil
j.saveSoon()
return true
end
j.log(1,Skc[1873],string.format(Skc[1874],M.name(hH.unit_id),tostring(fH.slot)))
return false
end
cb.REMOTE={feed=Skc[1853],fuse=Skc[1858]}
