function cb.hasWork(xH)
if not xH then
local yH=cb.focusReady()
if yH then
return Skc[1875]..M.name(yH.from)..Skc[1876],Skc[1750]
end
if O.snipeWanted()then
return Skc[1877]..M.name(H.snipeUnit)..Skc[1878],Skc[1879]
end
if O.snipeDue()then
return Skc[1880]..M.name(H.snipeUnit)..Skc[1881],Skc[1879]
end
if I.ownSwap then
return Skc[1882]..M.name(I.ownSwap.into)..Skc[1883],Skc[1884]
end
end
if not H.team or H.strDry then
return nil
end
cb.acts=cb.plan()
O.last.teamPlan=L.now()
local zH=cb.acts
if not xH then
zH={}
for AH,BH in ipairs(cb.acts)do
if not(BH.kind==Skc[1853]and(tonumber(BH.gain)or 0)<cb.FEED_STOP_GAIN)then
table.insert(zH,BH)
end
end
end
local CH=cb.nextAct(zH)
if CH then
return CH.text,CH.kind
end
if H.teamRelics and(tonumber(I.str.noWork.relic)or 0)<=os.time()and(not xH or not(H.autoTeam and H.play))then
local DH,EH=cb.relicPlan()
if EH and EH>=(xH and cb.relicBar()or cb.RELIC_SETTLED_GAIN)then
return string.format(Skc[1885],EH),Skc[1886]
