local Anb=tostring(xnb.r._r or(xnb.d..Skc[1480]..xnb.choice))..(ynb and(Skc[2056]..tostring(ynb))or Skc[299])..(znb and Skc[2491]or Skc[299])
local Bnb=bb.data()
