if#Jnb==0 then
Enb={none=true,sig=Dnb,at=os.time()}
else
local Knb=V.evaluate(Inb,V.teamFrom(Fnb,Inb.map))
Enb={p=Knb.p,wave=Knb.wave,won=Knb.won,total=Inb.total,margin=Knb.margin,sig=Dnb,at=os.time()}
