function bb.winP(Pnb)
local Qnb=tostring(math.min(4,math.max(1,math.ceil(Pnb.d/5))))
local Rnb=I.dg.depth[Qnb]or{runs=0,wins=0}
local Snb=L.clamp(0.95-0.015*Pnb.d,0.5,0.95)
local Tnb=((tonumber(Rnb.wins)or 0)+Snb*2)/((tonumber(Rnb.runs)or 0)+2)
local Unb,Vnb=pcall(bb.sim,Pnb)
if Unb and Vnb and Vnb.p then
Tnb=(Tnb*2+Vnb.p)/3
