function bb.curseOk(fob,gob,hob,iob,job)
local kob=tostring((bb.item(fob)or{}).name or fob)
local lob,mob,nob=bb.curseBar(gob,hob)
if lob>0.2 and bb.blindCurse(gob,fob)then
return false,string.format(Skc[2497],kob,nob)
end
local function oob(pob)
return pob==nil or(tonumber(pob.p)or 1)>=lob
end
if iob then
local qob,rob=pcall(bb.sim,iob,nil,true)
if qob and not oob(rob)then
return false,string.format(Skc[2498],kob,(mob:gsub(Skc[2499],Skc[2500])),tostring(rob.margin or Skc[1583]))
end
end
if#job==0 then
return true
end
local sob
for tob,uob in ipairs(job)do
local vob,wob=pcall(bb.sim,uob,fob,true)
