local Mob={}
for Nob,Oob in ipairs(Lob)do
table.insert(Mob,tostring(Oob.r._r))
end
local Pob=table.concat(Mob,Skc[1829])..string.format(Skc[2502],Job,Kob,Iob,N.teamSig())
if bb._pick and bb._pick.sig==Pob then
