local Vob,Wob
for Xob,Yob in ipairs(bb.after(Hob,Tob.choice))do
local Zob=bb.roomValue(Yob,Kob)
if not Vob or Zob>Vob then
Vob,Wob=Zob,Yob
end
end
local _ob,apb=bb.winP(Tob)
local bpb=1-(1-_ob)^math.max(1,Job)
local cpb=Job>=3 and 1 or(Job==2 and 2 or 6)
Tob.p,Tob.sim,Tob.value,Tob.nextValue,Tob.nextRoom=_ob,apb,Uob,Vob or 0,Wob
