Tob.blocked=fpb
end
if not Tob.blocked and(not Qob or Tob.score>Qob.score)then
Qob=Tob
end
if not Rob or Tob.score>Rob.score then
Rob=Tob
end
end
Qob=Qob or Rob
bb._pick={sig=Pob,x=Qob,rooms=Lob}
return Qob
end
