kqb.cost=math.ceil(kqb.cost*eqb)
table.insert(hqb,tostring(bb.item(kqb.id).name or kqb.id))
if not kqb.bought and not bb.isCurse(kqb.id)then
kqb.luck=tonumber(bb.item(kqb.id).luck_increase)~=nil
kqb.v=bb.itemValue(kqb.id,aqb)
if not kqb.luck and kqb.v/math.max(1,kqb.cost)<bb.MIN_WORTH then
iqb=iqb+1
elseif kqb.v>0 and(kqb.luck or cqb>=10 or kqb.v/math.max(1,kqb.cost)>=bb.TOP_WORTH)then
