end)
local nqb,oqb,pqb={},0,0
for qqb,rqb in ipairs(gqb)do
if rqb.cost<=dqb-(rqb.luck and 0 or fqb)then
if bb.buy(rqb)then
dqb=bb.res(bb.data())
table.insert(nqb,string.format(Skc[2515],tostring(bb.item(rqb.id).name or rqb.id),rqb.cost))
end
elseif rqb.cost<=dqb then
pqb=pqb+1
else
oqb=oqb+1
end
end
bb.note(string.format(Skc[2516],cqb,#hqb>0 and table.concat(hqb,Skc[1465])or Skc[2517],#nqb>0 and(Skc[2518]..table.concat(nqb,Skc[1465]))or(cqb<10 and Skc[2519]or(pqb>0 and Skc[2520]or Skc[2521])),dqb,oqb>0 and string.format(Skc[2522],oqb)or Skc[299],pqb>0 and string.format(Skc[2523],pqb,fqb)or Skc[299],iqb>0 and string.format(Skc[2524],iqb)or Skc[299]))
j.request(Skc[2525],Skc[2526])
end
