if hrb+irb<=0 or crb>=2 then
break
end
local jrb,krb
if hrb>0 then
jrb,krb=j.request(Skc[2540],Skc[2541])
else
jrb,krb=j.request(Skc[2540],Skc[2541],true)
end
if jrb and krb~=nil then
