end
local prb,qrb,rrb=bb.res(bb.data())
if qrb<hrb then
arb=arb+(hrb-qrb)
crb=0
elseif rrb<irb then
brb=brb+(irb-rrb)
crb=0
else
crb=crb+1
end
task.wait(1)
if qrb<hrb or rrb<irb then
local srb=bb.wallet()
local trb=bb.walletDiff(erb,srb)
j.log(1,Skc[2509],(rrb<irb and Skc[2543]or Skc[2542])..trb)
I.dg.pay=I.dg.pay or{}
local urb={}
for vrb,wrb in pairs(srb.items)do
