urb[vrb]=wrb-(erb.items[vrb]or 0)
end
end
table.insert(I.dg.pay,{at=os.time(),rare=rrb<irb,gems=srb.gems-erb.gems,luck=bb.luck(Uqb),paid=trb,items=urb})
