oub=oub+(lub[pub]-lub[pub-1]).Magnitude
end
local qub=0
for rub=2,#lub do
local tub,uub=lub[rub-1],lub[rub]
local vub=(uub-tub).Magnitude
local wub=math.max(1,math.floor(vub/2))
for xub=0,wub-1 do
local yub=tub:Lerp(uub,xub/wub)
table.insert(P.samples,{pos=yub,prog=(qub+vub*xub/wub)/math.max(1,oub),lane=jub.Name})
end
qub=qub+vub
end
if lub[#lub]then
table.insert(P.samples,{pos=lub[#lub],prog=1,lane=jub.Name})
end
end
end
local zub,Aub,Bub={},0,0
for Cub,Dub in ipairs(P.samples)do
local Eub=tostring(Dub.lane)
if not zub[Eub]then
Aub=Aub+1
end
zub[Eub]=(zub[Eub]or 0)+1
Bub=Bub+1
