local Mub,Nub=pcall(P.infStop,Jub)
if not Mub then
j.log(1,Skc[1899],Skc[2616]..tostring(Nub))
end
end
local Oub=N.infTier(Jub-1)
if Oub<=0 or Oub==P.infTierSeen then
return
end
P.infTierSeen=Oub
task.delay(5,function()
if not j.alive then
return
end
local Pub=G.prof()
local Qub=Pub and Pub.daily_infinite_reward_claims and Pub.daily_infinite_reward_claims[P.ld.id]
local Rub=type(Qub)==Skc[1370]and(tonumber(Qub.highest_claimed_wave)or 0)>=Oub and os.time()-(tonumber(Qub.highest_claim_time)or 0)<900
if Rub then
I.infLive=true
end
j.log(1,Skc[2617],string.format(Skc[2618],Oub,Rub and Skc[2619]or Skc[2620]))
end)
end
function P.infStop(Sub)
local Tub=0
for Uub,Vub in ipairs(L.list(G.GS.DAILY_INFINITE_REWARDS))do
Tub=math.max(Tub,tonumber(Vub.wave)or 0)
end
if Tub<=0 or Sub<=Tub+1 then
return
end
local Wub=I.train.on
if P.trainee and Wub and Wub.have+(Wub.got or 0)+(P.trainTk or 0)<Wub.need then
return
end
if not O.every(Skc[2621],60)then
return
end
local Xub=N.rec(P.key)
local Yub=tonumber(Xub.timed)or 0
local Zub=(Yub>0 and(Xub.sec or 0)>0)and math.max(0.5,((Xub.gems or 0)-200*Yub)/(Xub.sec/60))or 2.5
local _ub=pcall(N.pick)
local avb
for bvb,cvb in ipairs(_ub and N.lastScored or{})do
if cvb.kind~=Skc[1389]and(not avb or(cvb.score or 0)>(avb.score or 0))then
avb=cvb
end
end
if not avb or(avb.score or 0)<=Zub then
return
end
P.stopping=true
j.log(1,Skc[2617],string.format(Skc[2622],Sub,Zub,avb.score,avb.label))
P.sellAll()
end
function P.trainLeave(dvb)
local evb=I.train.on
if not(P.infinite and P.trainee and evb)then
return
end
P.trainCount()
local fvb=evb.have+(evb.got or 0)+(P.trainTk or 0)
if fvb<evb.need then
return
end
local gvb,hvb,ivb=pcall(N.infDaily,G.prof(),P.ld.id,(N.infReach(P.key)))
if gvb and(hvb or 0)>0 and ivb>0 and dvb<=ivb then
j.status(Skc[2076],string.format(Skc[2623],M.name(evb.id),evb.what,ivb))
return
end
P.stopping=true
j.log(1,Skc[2617],string.format(Skc[2624],M.name(evb.id),evb.what,L.fmt(fvb),L.fmt(evb.need),dvb))
P.sellAll()
end
function P.sellAll()
task.spawn(function()
local jvb={}
for kvb,lvb in ipairs(P.mine or{})do
local mvb=lvb:FindFirstChild(Skc[1429])
local nvb=mvb and mvb:FindFirstChild(Skc[2371])and G.Units[mvb.id.Value]
if not(nvb and nvb.unsellable)then
table.insert(jvb,lvb)
end
end
local function ovb(pvb)
local qvb=pvb:FindFirstChild(Skc[1429])
return qvb and qvb:FindFirstChild(Skc[2371])and M.isFarm(qvb.id.Value)or false
end
table.sort(jvb,function(rvb,svb)
return(ovb(rvb)and 1 or 0)<(ovb(svb)and 1 or 0)
end)
local tvb={}
for uvb=1,2 do
local vvb={}
for wvb,xvb in ipairs(uvb==1 and jvb or tvb)do
if not j.alive or P.finished then
return
end
if xvb.Parent and xvb.Parent.Name==Skc[2625]then
local yvb,zvb=j.request(Skc[2626],Skc[2627],xvb)
if zvb~=true then
table.insert(vvb,xvb)
end
task.wait(1.3)
end
end
tvb=vvb
end
if#tvb>0 then
local Avb={}
for Bvb,Cvb in ipairs(tvb)do
table.insert(Avb,Cvb.Name)
end
j.log(1,Skc[2617],Skc[2628]..table.concat(Avb,Skc[1465])..Skc[2629])
end
end)
end
function P.waveReward(Dvb)
if P.info then
return V.waveYen(P.info,Dvb)
end
local Evb=P.waveList and P.waveList[Dvb]
return(Evb and tonumber(Evb.wave_reward)or 0)*2.6
end
function P.progressAt(Fvb)
local Gvb,Hvb,Ivb=0,math.huge,nil
local Jvb=L.flat(Fvb)
for Kvb,Lvb in ipairs(P.samples)do
local Mvb=(L.flat(Lvb.pos)-Jvb).Magnitude
if Mvb<Hvb then
Hvb,Gvb,Ivb=Mvb,Lvb.prog,Lvb.lane
end
end
return Gvb,Hvb,Ivb~=nil and tostring(Ivb)or nil
end
function P.scan()
local Nvb,Ovb={},{}
for Pvb,Qvb in ipairs({workspace._UNITS})do
for Rvb,Svb in ipairs(Qvb:GetChildren())do
local Tvb=Svb:FindFirstChild(Skc[1429])
if Tvb and Tvb:FindFirstChild(Skc[2630])then
local Uvb=Tvb:FindFirstChild(Skc[2631])
local Vvb=Uvb and Uvb.Value
local Wvb=Vvb and Vvb:FindFirstChild(Skc[1429])
local Xvb=G.Units[Tvb.id.Value]
local Yvb=Vvb~=nil and Xvb~=nil and(tonumber(Xvb.cost)or 0)>=100 and(not Wvb or(Wvb:FindFirstChild(Skc[2371])and Wvb.id.Value==Tvb.id.Value))
if Tvb.id.Value==Skc[2632]then
Yvb=true
end
local Zvb=(Vvb~=nil and not Yvb)or not Tvb:FindFirstChild(Skc[1504])or not Tvb:FindFirstChild(Skc[1456])or not Tvb:FindFirstChild(Skc[1506])
if Tvb.player.Value==F then
if not Zvb then
table.insert(Ovb,Svb)
end
elseif Tvb.player.Value==nil and Svb:FindFirstChild(Skc[2633])then
local _vb,awb,bwb=P.progressAt(Svb.HumanoidRootPart.Position)
local cwb=Svb:FindFirstChildOfClass(Skc[2634])
local dwb=cwb and cwb.Health or(Tvb:FindFirstChild(Skc[2268])and Tvb.health.Value)or 0
local ewb=Tvb:FindFirstChild(Skc[2393])and tonumber(Tvb.damage_reduction.Value)or 0
local fwb=P.info and P.info.cfgById[Tvb.id.Value]
local gwb=Tvb:FindFirstChild(Skc[2480])and(tonumber(Tvb.Flying.Value)or 0)>0 or false
local hwb=Tvb:FindFirstChild(Skc[2635])and tonumber(Tvb.shield.Value)or 0
table.insert(Nvb,{m=Svb,pos=Svb.HumanoidRootPart.Position,prog=_vb,lane=bwb,hp=dwb,red=ewb,fly=gwb,sh=hwb,boss=fwb and tostring(fwb):find(Skc[2392])~=nil or false})
end
end
end
end
P.enemies,P.mine=Nvb,Ovb
if not P.flyerSeen then
for iwb,jwb in ipairs(Nvb)do
if jwb.fly then
P.flyerSeen=math.max(1,P.wave())
if not P.random then
j.log(1,Skc[2617],string.format(Skc[2636],P.flyerSeen))
end
break
end
end
end
if not P.shieldSeen then
for kwb,lwb in ipairs(Nvb)do
if(lwb.sh or 0)>0 then
P.shieldSeen=true
local mwb=lwb.m._stats
j.log(1,Skc[2617],string.format(Skc[2637],P.wave(),tostring(lwb.sh),tostring(mwb:FindFirstChild(Skc[2638])and mwb.max_shield.Value),tostring(mwb:FindFirstChild(Skc[2371])and mwb.id.Value),lwb.hp,tostring(P.info and P.info.shield)))
break
end
end
end
local nwb=P.wave()
local owb=0
local pwb,qwb,rwb=0,0,0
for swb,twb in ipairs(Nvb)do
owb=math.max(owb,twb.prog)
pwb=pwb+twb.hp/math.max(0.1,1-twb.red)
rwb=rwb+twb.hp
end
P.hpAliveRaw=rwb
for uwb,vwb in ipairs(Ovb)do
local wwb=vwb._stats.id.Value
if not M.isFarm(wwb)and vwb._stats:FindFirstChild(Skc[1503])then
local xwb,ywb=pcall(P.liveDps,vwb,wwb)
if xwb and ywb then
qwb=qwb+ywb
end
end
end
P.hpAlive,P.teamDps=pwb,qwb
P.clearSec=pwb>0 and(qwb>0 and pwb/qwb or math.huge)or 0
P.waveMax[nwb]=math.max(P.waveMax[nwb]or 0,owb)
P.front=owb
P.pressure=math.max(P.waveMax[nwb]or 0,P.waveMax[nwb-1]or 0)
P.depth=P.coverage(Ovb,Nvb)
local zwb=L.now()
P.aliveHist=P.aliveHist or{}
table.insert(P.aliveHist,{t=zwb,n= #Nvb})
while P.aliveHist[1]and zwb-P.aliveHist[1].t>12 do
table.remove(P.aliveHist,1)
end
local Awb=P.aliveHist[1]
P.piling= #Nvb>=8 and Awb and zwb-Awb.t>=8 and#Nvb>Awb.n+1 or false
if#Nvb>=18 then
P.piling=true
end
end
function P.setupChecks()
P.probe=Instance.new(Skc[2639])
P.probe.Name=Skc[2640]
P.probe.Anchored=true
P.probe.CanCollide=false
P.probe.CanTouch=false
P.probe.CanQuery=false
P.probe.Transparency=1
P.probe.Parent=workspace:FindFirstChild(Skc[2641])or workspace
local Bwb=s:FindFirstChild(Skc[2642])
P.bounds=Instance.new(Skc[2643])
P.bounds.Name=Skc[2644]
if Bwb then
for Cwb,Dwb in ipairs(Bwb:GetDescendants())do
if Dwb:IsA(Skc[2645])then
local Ewb=Dwb:Clone()
for Fwb,Gwb in ipairs(Ewb:GetChildren())do
