function P.spotKey(Hwb)
return string.format(Skc[2646],math.floor(Hwb.X+0.5),math.floor(Hwb.Z+0.5))
end
function P.killZone()
return H.killZone~=false and(P.style==Skc[2403]or(P.style==nil and P.kind==Skc[1390]))
end
function P.blockedSpot(Iwb)
local Jwb=P.spotKey(Iwb)
if P.refused[Jwb]then
return true
end
local Kwb=I.blocked[P.mapKey()]
return Kwb and(tonumber(Kwb[Jwb])or 0)>=2
end
function P.valid(Lwb,Mwb)
local Nwb=G.PC.raycast(Lwb+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not Nwb then
return nil
end
if not G.PC.is_valid_raycast_hit(Nwb.Instance,Mwb)then
return nil
end
local Owb=Nwb.Position
if P.blockedSpot(Owb)then
return nil
end
local Pwb=(tonumber(Mwb.override_hitbox_radius)or 1.5)+0.25
P.probe.Size=Vector3 .new(Pwb*2,2.5,Pwb*2)
P.probe.CFrame=CFrame.new(Owb+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(P.probe,P.overlap)>0 then
return nil
end
for Qwb,Rwb in ipairs(P.mine or{})do
local Swb=Rwb:FindFirstChild(Skc[2647])
local Twb=Swb and Swb.Position or Rwb:GetPivot().Position
local Uwb=Swb and math.max(Swb.Size.X,Swb.Size.Z)/2 or 1.5
if(L.flat(Owb)-L.flat(Twb)).Magnitude<Pwb+Uwb then
return nil
end
end
return Owb
end
function P.buildCandidates()
P.cands={}
local Vwb={}
for Wwb=1,#P.samples,3 do
local Xwb=P.samples[Wwb]
local Ywb=P.samples[math.min(#P.samples,Wwb+1)]
local Zwb=L.flat(Ywb.pos-Xwb.pos)
if Zwb.Magnitude<0.01 then
Zwb=Vector3 .new(1,0,0)
end
Zwb=Zwb.Unit
local _wb=Vector3 .new(-Zwb.Z,0,Zwb.X)
for axb,bxb in ipairs({3,4.5,6,8,10.5,13.5,17})do
for cxb,dxb in ipairs({1,-1})do
local exb=Xwb.pos+_wb*bxb*dxb
local fxb=string.format(Skc[2646],math.floor(exb.X/1.5),math.floor(exb.Z/1.5))
if not Vwb[fxb]then
Vwb[fxb]=true
table.insert(P.cands,exb)
end
end
end
end
end
function P.coverage(gxb,hxb)
local ixb={}
for jxb,kxb in ipairs(gxb)do
local lxb=kxb._stats
if not M.isFarm(lxb.id.Value)and lxb:FindFirstChild(Skc[1506])then
table.insert(ixb,{p=L.flat(kxb:GetPivot().Position),r=lxb.range.Value*(M.SUMMONER[lxb.id.Value]and M.SUMMONER[lxb.id.Value].reach or 1),air=P.canAir(kxb)})
end
end
local mxb,nxb=0,0
if#ixb>0 then
for oxb,pxb in ipairs(P.samples)do
if pxb.prog>nxb then
local qxb=L.flat(pxb.pos)
for rxb,sxb in ipairs(ixb)do
if(qxb-sxb.p).Magnitude<=sxb.r then
if pxb.prog>mxb then
mxb=pxb.prog
end
if sxb.air then
nxb=pxb.prog
break
end
end
end
end
end
end
local txb,uxb={},P.laneCount
if uxb and uxb.n>=2 and#ixb>0 then
local vxb={}
for wxb,xxb in ipairs(P.samples)do
local yxb=L.flat(xxb.pos)
for zxb,Axb in ipairs(ixb)do
if(yxb-Axb.p).Magnitude<=Axb.r then
local Bxb=tostring(xxb.lane)
vxb[Bxb]=(vxb[Bxb]or 0)+1
if xxb.prog>(txb[Bxb]or 0)then
txb[Bxb]=xxb.prog
end
break
end
end
end
local Cxb,Dxb={},0
for Exb,Fxb in pairs(uxb.by)do
Cxb[Exb]=(vxb[Exb]or 0)/math.max(1,Fxb)
Dxb=math.max(Dxb,Cxb[Exb])
end
P.laneW={}
for Gxb,Hxb in pairs(uxb.by)do
P.laneW[Gxb]=(uxb.avg/math.max(1,Hxb))*(1+1.5*(Dxb>0 and(1-Cxb[Gxb]/Dxb)or 0))
end
P.laneFrac=Cxb
else
P.laneW,P.laneFrac=nil,nil
end
local Ixb,Jxb,Kxb
if#ixb>0 then
for Lxb,Mxb in ipairs(hxb)do
local Nxb=(P.laneW and Mxb.lane and txb[Mxb.lane])or mxb
if Mxb.hp>0 and Mxb.prog>Nxb+0.02 and Mxb.prog>(Ixb or 0)then
Ixb,Kxb=Mxb.prog,P.laneW and Mxb.lane or nil
end
if Mxb.hp>0 and Mxb.fly and Mxb.prog>nxb+0.02 then
Jxb=true
end
end
end
local Oxb= #ixb>0 and(P.pressure or 0)>=mxb-0.08
return{covEnd=mxb,airEnd=nxb,leak=Ixb,leakLane=Kxb,covL=txb,airLeak=Jxb,push=Oxb,units= #ixb}
end
function P.needLastLine(Pxb)
if M.isFarm(Pxb.id)or M.allyBuff(Pxb.id)or P.fieldCount()<5 then
return false
end
local Qxb,Rxb=0,0
for Sxb,Txb in ipairs(P.mine or{})do
local Uxb=Txb._stats
if not M.isFarm(Uxb.id.Value)and Uxb:FindFirstChild(Skc[1506])then
local Vxb,Wxb=L.flat(Txb:GetPivot().Position),Uxb.range.Value
for Xxb,Yxb in ipairs(P.samples)do
if Yxb.prog>=0.85 and(L.flat(Yxb.pos)-Vxb).Magnitude<=Wxb then
Qxb=Qxb+1
if P.canAir(Txb)then
Rxb=Rxb+1
end
break
end
end
end
end
return Qxb<2 or(Rxb<1 and P.flyMode()and P.cardAir(Pxb.id))
end
P.airCache=setmetatable({},{__mode=Skc[2648]})
function P.canAir(Zxb)
local _xb=Zxb._stats:FindFirstChild(Skc[1456])and Zxb._stats.upgrade.Value or 0
local ayb=P.airCache[Zxb]
if not ayb or ayb.lvl~=_xb then
local byb=Zxb:GetAttribute(Skc[2649])==true or Zxb:GetAttribute(Skc[2650])==true
ayb={lvl=_xb,v=byb}
P.airCache[Zxb]=ayb
end
return ayb.v
end
M._airFrom={}
function M.airFrom(cyb)
local dyb=M._airFrom[cyb]
if dyb~=nil then
return dyb or nil
end
local eyb=G.Units[cyb]
if eyb and(eyb.hill_unit or eyb.hybrid_placement or M.SUMMONER[cyb])then
M._airFrom[cyb]=0
return 0
end
local fyb=M.rows(cyb)
if not(fyb and fyb.max)then
return P.cardAir(cyb)and 0 or nil
end
local gyb=false
for hyb=0,fyb.max do
local iyb=fyb[hyb]and fyb[hyb].atk
if iyb and G.Attacks[iyb]and G.Attacks[iyb].targets_flying then
gyb=hyb
break
end
end
if gyb==false and P.cardAir(cyb)then
gyb=0
end
M._airFrom[cyb]=gyb
return gyb or nil
end
function P.cardAir(jyb)
local kyb=G.Units[jyb]
if not kyb then
return false
end
if kyb.hill_unit or kyb.hybrid_placement then
return true
end
local lyb=M.field(jyb,Skc[1459])or M.field(jyb,Skc[1458])
return lyb and G.Attacks[lyb]and G.Attacks[lyb].targets_flying and true or false
end
function P.airShare()
local myb,nyb=0,0
for oyb,pyb in ipairs(P.mine or{})do
local qyb=pyb._stats.id.Value
if not M.isFarm(qyb)then
local ryb,syb=pcall(P.liveDps,pyb,qyb)
syb=ryb and syb or 0
myb=myb+syb
if P.canAir(pyb)then
nyb=nyb+syb
end
end
end
return myb>0 and nyb/myb or 0
end
function P.cover(tyb,uyb,vyb,wyb)
local xyb=0
local yyb=L.flat(tyb)
local zyb=vyb and I.maps[P.mapKey()]and I.maps[P.mapKey()].dens
local Ayb=P.laneW
for Byb,Cyb in ipairs(P.samples)do
if(L.flat(Cyb.pos)-yyb).Magnitude<=uyb then
local Dyb=1
if zyb then
Dyb=0.15+0.85*(tonumber(zyb[math.min(V.BINS,math.floor(Cyb.prog*V.BINS)+1)])or 0)
end
if Ayb then
Dyb=Dyb*(Ayb[tostring(Cyb.lane)]or 1)
end
if wyb then
if wyb.leak and Cyb.prog>=wyb.leak-0.01 and(not wyb.leakLane or tostring(Cyb.lane)==wyb.leakLane)then
Dyb=Dyb+3
elseif wyb.push and Cyb.prog>wyb.covEnd then
Dyb=Dyb+0.6
end
end
xyb=xyb+Dyb
end
end
return xyb
end
function P.bleedGain(Eyb,Fyb,Gyb)
local Hyb=P.info and tonumber(P.info.regen)or 0
if Hyb<=0 then
return 0
end
local Iyb=M.bleeds(Eyb)
if not Iyb then
return 0
end
local Jyb=false
for Kyb,Lyb in ipairs(P.mine or{})do
local Myb=Lyb:FindFirstChild(Skc[1429])
local Nyb=Myb and Myb:FindFirstChild(Skc[2371])and Myb.id.Value
local Oyb=Myb and Myb:FindFirstChild(Skc[1456])and tonumber(Myb.upgrade.Value)or 0
if Nyb and(M.bleeds(Nyb)or 99)<=Oyb then
Jyb=true
break
end
end
return U.bleedShare(U.bleedGain(Hyb,P.hpAlive or 0,P.coming,Jyb),Iyb,Fyb,Gyb)
end
function P.fieldBuffers()
local Pyb={}
for Qyb,Ryb in ipairs(P.mine or{})do
local Syb=M.allyBuff(Ryb._stats.id.Value)
if Syb then
table.insert(Pyb,{pos=Ryb:GetPivot().Position,range=Ryb._stats.range.Value,b=Syb})
end
end
return Pyb
end
function P.buffShort(Tyb)
local Uyb={}
for Vyb,Wyb in ipairs(P.fieldBuffers())do
if Wyb.b.attack==Tyb.attack then
table.insert(Uyb,Wyb)
end
end
local Xyb=M.buffCopies(Tyb)
local Yyb={}
for Zyb,_yb in ipairs(P.mine or{})do
local azb=_yb._stats.id.Value
local bzb,czb=M.types(azb)
if not M.isFarm(azb)and not M.allyBuff(azb)and Tyb.types[czb]then
local dzb=L.flat(_yb:GetPivot().Position)
local ezb=0
for fzb,gzb in ipairs(Uyb)do
if(L.flat(gzb.pos)-dzb).Magnitude<=gzb.range then
ezb=ezb+1
end
end
if ezb<Xyb then
local hzb,izb=pcall(P.liveDps,_yb,azb)
table.insert(Yyb,{pos=dzb,base=czb,n=ezb,dps=math.max(1,hzb and tonumber(izb)or 1)})
end
end
end
return Yyb
end
function P.spotRec(jzb,kzb,lzb)
local mzb=P.mapKey()
I.maps[mzb]=I.maps[mzb]or{}
local nzb=I.maps[mzb].lay
if not nzb then
if not lzb then
return nil
end
nzb={}
I.maps[mzb].lay=nzb
end
local ozb=nzb[jzb]
if not ozb then
if not lzb then
return nil
end
ozb={}
nzb[jzb]=ozb
end
local pzb=P.spotKey(kzb)
if not ozb[pzb]and lzb then
ozb[pzb]={runs=0,wins=0}
end
return ozb[pzb]
end
function P.lastLife(qzb,rzb)
if P.kind~=Skc[1390]then
return
end
local szb,tzb=pcall(bb.lives,bb.data())
if not(szb and tzb<=1)then
return
end
local uzb=qzb>1 or rzb.won
bb.note(string.format(Skc[2651],uzb and Skc[1693]or(Skc[2652]..rzb.wave)))
if not uzb and bb.playLast()then
bb.note(Skc[2653])
elseif not uzb then
P.noBuy=true
N.rec(Skc[1675]).restUntil=os.time()+3600
I.pending=nil
bb.note(Skc[2654])
j.saveNow()
task.wait(1)
j.request(Skc[1437],Skc[2655])
