if oHb and pHb then
P.spent=P.spent+(iHb.data.cost or 0)
table.insert(P.actions,string.format(Skc[2701],M.name(iHb.id)))
j.log(1,Skc[2693],string.format(Skc[2702],M.name(iHb.id),P.spotKey(lHb),mHb,jHb))
P.placeLog=P.placeLog or{}
table.insert(P.placeLog,{t=math.floor(L.now()-(P.startT or L.now())),w=P.wave(),id=iHb.id,x=math.floor(lHb.X),z=math.floor(lHb.Z),cover=math.floor((mHb or 0)+0.5),why=tostring(jHb):sub(1,90)})
