P.noSpot[iHb.uuid]=3
j.log(1,Skc[2693],string.format(Skc[2704],M.name(iHb.id),P.fieldCount(),P.FIELD_MAX))
end
end
if oHb and nHb>=(iHb.data.cost or 0)and not P.random then
local qHb=P.spotKey(lHb)
P.refused[qHb]=true
local rHb=P.mapKey()
I.blocked[rHb]=I.blocked[rHb]or{}
if not P.refusedRun[qHb]then
