return KQb
end
function P.huntRecord(LQb,MQb,NQb,OQb)
local PQb=db.floor()
I.hunt.pmin=L.clamp(PQb+(NQb and-0.1 or 0.1),0.4,2)
I.hunt.runs=I.hunt.runs or{}
table.insert(I.hunt.runs,1,{at=os.time(),wave=P.wave(),won=NQb or nil,pearls=MQb,mult=P.fhMult or 1,strength=P.fhP or 1,floor=PQb,map=P.ld.map,weather=db.weatherNow(),sec=OQb,picks=P.fhPicks})
while#I.hunt.runs>20 do
