end
local QQb=db.board()
j.log(1,Skc[2814],string.format(Skc[2815],NQb and Skc[1697]or Skc[1698],P.wave(),(tonumber(OQb)or 0)/60,MQb,P.fhMult or 1,tostring(P.ld.map),tostring(db.weatherNow()),QQb and string.format(Skc[2816],QQb.squares,#QQb.board)or Skc[299]))
local RQb={}
for SQb,TQb in ipairs({Skc[2817],Skc[2818],Skc[2819],Skc[2820],Skc[2821],Skc[2822],Skc[2823],Skc[2824]})do
if type(LQb)==Skc[1370]then
RQb[TQb]=LQb[TQb]
end
