function P.pickRogue()
local YQb=P.rogueOptions
if YQb and P.hunt then
return P.huntPick(YQb)
end
if not YQb then
local ZQb=j.request(Skc[2808],Skc[2809],1)
return ZQb
end
P.fhP=P.fhP or 1
local _Qb=tonumber(I.fh.pmin)or 1
local aRb=(P.pressure or 0)>=H.safeReach or(P.depth and P.depth.leak)
local bRb,cRb,dRb
for eRb,fRb in pairs(YQb)do
local gRb,hRb=1,0
for iRb,jRb in pairs(type(fRb)==Skc[1370]and fRb.effects or{})do
if type(jRb)==Skc[1370]then
local kRb,lRb=P.rogueEffect(jRb)
gRb=gRb*kRb
hRb=hRb+lRb
end
end
local mRb=math.log(math.max(0.05,gRb))*10
if hRb>0 and P.fhP*gRb>=_Qb and not aRb then
mRb=mRb+100*hRb
elseif hRb>0 then
mRb=mRb-50+hRb
end
if not cRb or mRb>cRb then
bRb,cRb,dRb=eRb,mRb,gRb
end
end
P.fhP=P.fhP*(dRb or 1)
local nRb={}
for oRb,pRb in pairs(YQb)do
local qRb={}
for rRb,sRb in pairs(type(pRb)==Skc[1370]and pRb.effects or{})do
if type(sRb)==Skc[1370]then
table.insert(qRb,P.effectText(sRb))
end
end
table.insert(nRb,tostring(oRb)..Skc[2827]..table.concat(qRb,Skc[2458]))
end
P.rogueOptions=nil
local tRb=j.request(Skc[2808],Skc[2809],bRb)
j.log(1,Skc[2810],string.format(Skc[2828],P.wave(),tostring(bRb),cRb or 0,P.fhP,_Qb,table.concat(nRb,Skc[2813])))
return tRb
end
function P.rogueShare(uRb)
if not uRb then
return 0.5
end
local vRb=tostring(uRb):gsub(Skc[2829],Skc[299])
local wRb,xRb=0,0
for yRb,zRb in ipairs(P.mine or{})do
local ARb=zRb._stats.id.Value
if not M.isFarm(ARb)then
local BRb,CRb=pcall(P.liveDps,zRb,ARb)
CRb=BRb and CRb or 0
local DRb=M.types(ARb)
wRb=wRb+CRb
if DRb[vRb]or DRb[vRb..Skc[2460]]then
xRb=xRb+CRb
end
end
end
local ERb=0
for FRb,GRb in ipairs(P.mine or{})do
if not M.isFarm(GRb._stats.id.Value)then
ERb=ERb+1
end
end
local HRb=ERb/(ERb+4)
return HRb*(wRb>0 and xRb/wRb or 0.5)+(1-HRb)*0.5
end
function P.resistOf(IRb)
local JRb=M.types(IRb)
local KRb=0
for LRb,MRb in pairs(P.fhResist or{})do
local NRb=tostring(LRb):gsub(Skc[2829],Skc[299])
if JRb[NRb]or JRb[NRb..Skc[2460]]then
KRb=math.max(KRb,MRb/100)
end
end
return math.min(0.95,KRb)
end
function P.rogueEffect(ORb)
local PRb,QRb,RRb=ORb.type,tonumber(ORb.amount)or 0,tostring(ORb.stat or Skc[299])
if PRb==Skc[1575]then
return 1,math.abs(QRb)
end
if PRb==Skc[2463]or PRb==Skc[2468]or PRb==Skc[2464]then
if RRb==Skc[1503]then
return math.max(0.3,1+QRb),0
end
if RRb==Skc[1506]then
return math.max(0.5,1+QRb/2),0
end
if RRb:find(Skc[2482])then
return 1/math.max(0.3,1+QRb),0
end
return 1,0
end
if PRb==Skc[2830]then
if RRb==Skc[1503]then
return math.max(0.3,QRb),0
end
if RRb==Skc[1506]then
return math.max(0.5,1+(QRb-1)/2),0
end
if RRb:find(Skc[2482])then
return 1/math.max(0.3,QRb),0
end
return 1,0
end
if PRb==Skc[2470]then
return 1+QRb/3,0
end
if PRb==Skc[2476]then
return 1/math.max(0.3,1+QRb),0
end
if PRb==Skc[2831]then
return math.max(0.2,1-P.rogueShare(ORb.damage_type)*(1-100/(100+QRb))),0
end
if PRb==Skc[2832]then
return 1+P.rogueShare(ORb.damage_type)*QRb,0
end
if PRb==Skc[2833]then
return math.max(0.5,1-QRb*0.5),0
end
if PRb==Skc[2834]then
return math.max(0.5,1-QRb*0.2),0
end
if PRb==Skc[2835]then
return 1+QRb*0.1,0
end
if PRb==Skc[2836]then
return 1/math.max(0.3,1+QRb*0.5),0
end
if PRb==Skc[2837]then
return math.max(0.5,1-QRb*0.1),0
end
if PRb==Skc[2471]then
return 1/math.max(0.3,1+QRb),0
end
if PRb==Skc[2477]then
return math.max(0.3,1-QRb*20),0
end
if PRb==Skc[2478]then
return math.max(0.5,1-QRb*0.03),0
end
if PRb==Skc[2838]then
return 0.95,0
end
if PRb==Skc[2479]then
return math.max(0.5,1-QRb),0
end
if PRb==Skc[2839]then
return 1+math.min(0.3,QRb/40000),0
end
if PRb==Skc[2472]then
return 1/math.max(0.3,1+QRb/2),0
end
if PRb==Skc[2840]then
return 0.8,0
end
if PRb==Skc[2841]then
local SRb=math.max(1,math.abs(QRb))*math.max(1,math.abs(tonumber(ORb.tier)or 1))
return ORb._type==Skc[2842]and 1.1^SRb or 0.8^SRb,0
end
return 1,0
end
function P.effectText(TRb)
return string.format(Skc[2843],tostring(TRb.type),TRb.stat and(Skc[1609]..tostring(TRb.stat))or Skc[299],tostring(TRb.amount))
end
function P.learn()
local URb,VRb={},{}
local WRb,XRb=0,0
for YRb,ZRb in ipairs(P.mine)do
local _Rb=ZRb._stats
local aSb=_Rb.id.Value
local bSb=_Rb:FindFirstChild(Skc[2711])and _Rb.total_damage.Value or 0
if not M.isFarm(aSb)then
URb[aSb]=(URb[aSb]or 0)+bSb
VRb[aSb]=(VRb[aSb]or 0)+P.liveDps(ZRb,aSb)/math.max(0.5,M.nudge(aSb))
local cSb=M.passive(aSb).mark
if cSb then
VRb[aSb]=VRb[aSb]+cSb.dot*_Rb.damage.Value
end
WRb=WRb+bSb
end
end
for dSb,eSb in pairs(VRb)do
XRb=XRb+eSb
end
if WRb<=0 or XRb<=0 then
return
end
P.lastEff={}
for fSb,gSb in pairs(URb)do
local hSb,iSb=gSb/WRb,VRb[fSb]/XRb
if iSb>0.02 then
local jSb=I.learn[fSb]or{eff=1,n=0}
local kSb=math.max(0.02,0.25*math.sqrt(30/(30+jSb.n)))
local lSb=L.clamp(hSb/iSb,0.3,3)
P.lastEff[fSb]=math.floor(lSb*1000+0.5)/1000
jSb.eff=jSb.eff+(lSb-jSb.eff)*kSb
jSb.n=jSb.n+1
I.learn[fSb]=jSb
end
end
end
function P.randomTeam()
local mSb=G.session()
local nSb=mSb and mSb.collection.temporary_units or{}
local oSb,pSb={},{}
local function qSb(rSb,sSb,tSb)
local uSb=rSb and nSb[rSb]
if uSb and G.Units[uSb.unit_id]and not pSb[rSb]then
pSb[rSb]=true
table.insert(oSb,{slot=tSb or 99,uuid=rSb,u=uSb,id=uSb.unit_id,data=G.Units[uSb.unit_id],hand=sSb})
end
end
for vSb,wSb in pairs(mSb and mSb.override_equipped_units or{})do
qSb(wSb,true,tonumber(vSb))
end
for xSb,ySb in ipairs(P.mine or{})do
local zSb=ySb._stats
qSb(zSb:FindFirstChild(Skc[2696])and zSb.uuid.Value,false)
end
table.sort(oSb,function(ASb,BSb)
return ASb.slot<BSb.slot
end)
return oSb
end
function P.fhSnap()
local CSb,DSb=nil,nil
pcall(function()
for ESb,FSb in ipairs(workspace._BASES:GetDescendants())do
if FSb:IsA(Skc[2634])then
CSb,DSb=FSb.Health,FSb.MaxHealth
break
end
end
end)
local GSb=CSb and DSb and DSb>0 and math.floor(CSb/DSb*100)or-1
local HSb,ISb,JSb=0,{},{}
for KSb,LSb in ipairs(P.enemies or{})do
if(LSb.prog or 0)>0.8 then
HSb=HSb+1
ISb[tostring(LSb.m)]=(ISb[tostring(LSb.m)]or 0)+1
end
JSb[tostring(LSb.m)]=(JSb[tostring(LSb.m)]or 0)+1
end
if not next(ISb)then
ISb=JSb
end
local MSb=0
for NSb,OSb in ipairs(P.mine or{})do
local PSb,QSb=pcall(P.liveDps,OSb,OSb._stats.id.Value)
if PSb and QSb then
MSb=MSb+QSb
end
end
P.fhWaves=P.fhWaves or{}
local RSb=0
for SSb,TSb in ipairs(P.enemies or{})do
if TSb.fly then
RSb=RSb+1
end
end
table.insert(P.fhWaves,string.format(Skc[2844],P.wave(),GSb,#(P.enemies or{}),HSb,L.fmt(MSb),P.fieldCount(),P.fhMult or 1,L.fmt(P.money()),math.floor(P.airShare()*100+0.5),RSb))
if GSb>=0 and P.fhLastPct and GSb<P.fhLastPct and not P.fhLeak then
local USb={}
for VSb,WSb in pairs(ISb)do
table.insert(USb,M.name(VSb)..Skc[2845]..WSb)
end
P.fhLeak=string.format(Skc[2846],P.wave(),P.fhLastPct,GSb,#USb>0 and table.concat(USb,Skc[1465])or Skc[2538])
j.log(1,Skc[2617],Skc[2847]..P.fhLeak)
end
P.fhLastPct=GSb
end
function P.fhRecord(XSb,YSb)
local ZSb,_Sb={},0
for aTb,bTb in ipairs(P.mine or{})do
local cTb=bTb._stats
local dTb=cTb:FindFirstChild(Skc[2711])and tonumber(cTb.total_damage.Value)or 0
local eTb=cTb.id.Value
if dTb>0 then
ZSb[eTb]=(ZSb[eTb]or 0)+dTb
_Sb=_Sb+dTb
end
end
local fTb={}
for gTb,hTb in pairs(ZSb)do
local iTb=_Sb>0 and hTb/_Sb or 0
local jTb=I.fh.units[gTb]or{n=0,share=0}
jTb.share=(jTb.share*jTb.n+iTb)/(jTb.n+1)
jTb.n=jTb.n+1
I.fh.units[gTb]=jTb
table.insert(fTb,{id=gTb,share=iTb})
end
table.sort(fTb,function(kTb,lTb)
return kTb.share>lTb.share
end)
local mTb={}
for nTb=1,math.min(4,#fTb)do
table.insert(mTb,string.format(Skc[1690],M.name(fTb[nTb].id),math.floor(fTb[nTb].share*100+0.5)))
end
pcall(P.fhSnap)
local oTb=tonumber(I.fh.pmin)or 1
I.fh.pmin=L.clamp(oTb*(YSb and 0.9 or 1.1),0.5,2.5)
table.insert(I.fh.runs,1,{at=os.time(),wave=P.wave(),won=YSb or nil,coins=XSb,top=mTb,mult=P.fhMult or 1,discards=P.discards,strength=P.fhP,floor=oTb,effects=P.fhEffects,picks=P.fhPicks,leak=P.fhLeak,waves=P.fhWaves})
while#I.fh.runs>20 do
table.remove(I.fh.runs)
end
j.log(1,Skc[2848],string.format(Skc[2849],P.wave(),table.concat(mTb,Skc[1465])))
end
function P.carry(pTb)
local qTb=I.fh.units[pTb]
return qTb and qTb.n>0 and qTb.share or 0
end
function P.fhText()
local rTb=I.fh.runs
if#rTb==0 then
return Skc[2850]
end
local sTb,tTb=0,0
for uTb,vTb in ipairs(rTb)do
sTb=sTb+(vTb.wave or 0)
tTb=tTb+(vTb.coins or 0)
end
local wTb={}
for xTb,yTb in pairs(I.fh.units)do
if yTb.n>=2 then
table.insert(wTb,{id=xTb,share=yTb.share,n=yTb.n})
end
end
table.sort(wTb,function(zTb,ATb)
return zTb.share>ATb.share
end)
local BTb={}
for CTb=1,math.min(6,#wTb)do
table.insert(BTb,string.format(Skc[2851],M.name(wTb[CTb].id),math.floor(wTb[CTb].share*100+0.5),wTb[CTb].n))
end
local DTb=0
for ETb in pairs(I.unitData)do
DTb=DTb+1
end
local FTb=0
for GTb,HTb in ipairs(rTb)do
if HTb.won then
FTb=FTb+1
end
end
local ITb=rTb[1]
local JTb,KTb=I.fh.merge,I.fh.idol
local LTb=Skc[299]
if JTb and JTb.n>0 then
LTb=LTb..string.format(Skc[2852],JTb.n,JTb.ratio/JTb.n*100)
end
if KTb and KTb.n>0 then
LTb=LTb..string.format(Skc[2853],KTb.dmg/KTb.n*100,KTb.cost/KTb.n*100,KTb.n)
end
local MTb,NTb=I.fh.clone,I.fh.ritual
if MTb and MTb.n>0 then
LTb=LTb..string.format(Skc[2854],MTb.n,MTb.ratio/MTb.n*100,MTb.spent/MTb.n*100)
end
if NTb and NTb.n>0 then
LTb=LTb..string.format(Skc[2855],NTb.n,NTb.ratio/NTb.n)
end
local OTb=I.fh.farmMerge
if OTb and OTb.n>0 then
LTb=LTb..string.format(Skc[2856],OTb.n,OTb.ratio/OTb.n*100)
end
return string.format(Skc[2857]..Skc[2858]..Skc[2859],#rTb,FTb,sTb/ #rTb,math.floor(tTb/ #rTb+0.5),tostring(ITb.wave),tonumber(ITb.mult)or 1,tonumber(ITb.strength)or 1,ITb.leak and(Skc[2860]..ITb.leak)or Skc[299],table.concat(ITb.top or{},Skc[1465]),tonumber(I.fh.pmin)or 1,#BTb>0 and table.concat(BTb,Skc[1558])or Skc[2861],DTb,LTb)
end
function P.cardDps(PTb)
local QTb,RTb=pcall(M.dps,PTb.u,0,P.mod)
RTb=QTb and tonumber(RTb)or 0
if RTb>0 or M.isFarm(PTb.id)or M.idol(PTb.id)or M.allyBuff(PTb.id)then
return RTb
end
local STb=table.clone(P.cardVals or{})
if#STb==0 then
return 1000
end
table.sort(STb)
return STb[math.max(1,math.ceil(#STb*0.6))]
end
function P.cardValue(TTb)
if M.isFarm(TTb.id)then
return 0
end
if M.idol(TTb.id)then
return(P.teamDps or 0)*P.idolStep()*3
end
local UTb=M.allyBuff(TTb.id)and P.buffGain(TTb)or P.cardDps(TTb)
return UTb*(1+2*P.carry(TTb.id))*(1-P.resistOf(TTb.id))*P.airNeed(TTb.id)*(P.mergeIds[TTb.id]and 2 or 1)
end
function P.flyMode()
if P.random or P.flyerSeen then
return true
end
if P.kind==Skc[1390]then
if P._curseFly==nil then
local VTb,WTb=pcall(bb.items,bb.data())
P._curseFly=VTb and(WTb._curse_fly or 0)>0 or false
end
return P._curseFly
end
return false
end
function P.shieldNow()
local XTb=P.wave()
if P._shieldW~=XTb then
P._shieldW,P._shieldS,P._shieldH=XTb,0,1
local YTb,ZTb=pcall(V.wave,P.info,math.max(1,XTb),true)
if P.info and YTb and#ZTb>0 then
local _Tb,aUb=0,0
for bUb,cUb in ipairs(ZTb)do
_Tb,aUb=_Tb+(cUb.sh or 0),aUb+cUb.hp
end
P._shieldS,P._shieldH=_Tb/ #ZTb,aUb/ #ZTb
end
end
return P._shieldS,P._shieldH
end
function P.shieldOf(dUb,eUb)
local fUb,gUb=P.shieldNow()
if fUb<=0 or not eUb then
return dUb
end
local hUb=M.attackInfo(eUb.atk,eUb.range)
return U.shieldDps(dUb,tonumber(eUb.cd)or 2,hUb.n,fUb,gUb,P.info and P.info.eff,hUb.hits)
end
function P.shieldWork(iUb,jUb)
local kUb,lUb=P.shieldNow()
if kUb<=0 or not jUb or not P.info then
return 0
end
local mUb,nUb=0,0
for oUb,pUb in ipairs(P.team or{})do
local qUb=M.rows(pUb.id)
qUb=qUb and qUb[0]
if qUb and not M.isFarm(pUb.id)then
mUb=math.max(mUb,M.dps(pUb.u,0,P.mod)*(tonumber(qUb.cd)or 2)/math.max(1,M.attackInfo(qUb.atk,qUb.range).n))
end
end
for rUb,sUb in ipairs(P.mine or{})do
local tUb=sUb._stats.id.Value
local uUb=M.rows(tUb)
local vUb=uUb and uUb[sUb._stats.upgrade and sUb._stats.upgrade.Value or 0]
if vUb and not M.isFarm(tUb)and not M.allyBuff(tUb)then
local wUb=M.attackInfo(vUb.atk,vUb.range)
nUb=nUb+wUb.n*wUb.hits/math.max(0.3,tonumber(vUb.cd)or 2)
end
end
local xUb,yUb=pcall(V.wave,P.info,math.max(1,P.wave()),true)
local zUb=M.attackInfo(jUb.atk,jUb.range)
return U.shieldWork(zUb.n,tonumber(jUb.cd)or 2,nUb,kUb,xUb and#yUb or 1,P.info.waveSec,mUb*(P.info.eff or 1),lUb,zUb.hits)
end
function P.teamShield()
if P._shieldAt and L.now()-P._shieldAt<2 then
return P._shieldTeam
end
local AUb,BUb=0,0
for CUb,DUb in ipairs(P.mine or{})do
local EUb=DUb._stats.id.Value
if not M.isFarm(EUb)and DUb._stats:FindFirstChild(Skc[1456])then
local FUb=M.rows(EUb)
local GUb,HUb=pcall(P.liveDps,DUb,EUb)
if GUb and FUb then
AUb=AUb+HUb
BUb=BUb+P.shieldOf(HUb,FUb[DUb._stats.upgrade.Value])
end
end
end
P._shieldTeam,P._shieldAt=AUb>0 and math.max(0.05,BUb/AUb)or 1,L.now()
return P._shieldTeam
end
function P.airLow()
if not P.flyMode()then
return false
end
if O.every(Skc[2862],1)or not P.airShareNow then
P.airShareNow=P.airShare()
end
return P.airShareNow<0.5
end
function P.airWeight(IUb)
if not(IUb and P.flyMode())then
return 1
end
return P.airLow()and 2.5 or 1.5
end
function P.reach(JUb)
if not P.reachAt or L.now()-P.reachAt>5 then
local KUb,LUb=0,0
for MUb,NUb in ipairs(P.mine or{})do
local OUb=NUb._stats
if not M.isFarm(OUb.id.Value)and OUb:FindFirstChild(Skc[1506])then
KUb,LUb=KUb+P.cover(NUb:GetPivot().Position,OUb.range.Value),LUb+1
